#!/usr/bin/env python3
"""Render the complete split mapping and import immutable historical build evidence."""
import argparse,hashlib,json,pathlib,re

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--root',required=True);p.add_argument('--evidence-root');a=p.parse_args();root=pathlib.Path(a.root);audit=root/'daemon/patch-audit';m=json.loads((audit/'split-manifest.json').read_text());bysha={r['sha']:r for r in m['patches']}
 def label(row):return row['series']+f"/{row['number']:03}"
 lines=['# Logical patch split audit','','This candidate rewrites patch history only. It preserves all 84 original completed-patch trees exactly; source repairs and performance measurements remain separate. The exported series now has '+str(m['counts']['ecash'])+' Layer-1 and '+str(m['counts']['v2'])+' Layer-2 patches.','','**Review candidate: do not merge as a claim of standalone compilation.** Splitting cannot cure missing declarations, mismatched interfaces or known test failures already present in the original source. No repaired benchmark source trees were substituted.','','The outer worktree is `/private/tmp/wt-split-lotus-patches`, branch `review/split-lotus-patch-stack-20261018`. The independent source worktree is `/private/tmp/wt-split-lotus-source`, branch `review/split-lotus-source-20261018`. Neither active checkout or benchmark data is changed.','','## What changed','','Original ecash/020 was a 47-file catch-up commit with 5,509 additions and 1,094 removals. Its three-line message omitted most of the implementation. Its extracted parts follow; production edits inside `validation.cpp`, `v2_protocol_handler.cpp` and other shared files are assigned to the responsible behavior rather than copied as whole files.','', '| New patch | Concern | Files |','|---|---|---|']
 for r in m['patches']:
  if r['original_patch']=='ecash/020':lines.append('| '+label(r)+' | '+r['subject'].replace('|','\\|')+' | '+str(len(r['files']))+' |')
 lines+=['','The historical rollback part explicitly contains APIs, lazy-overlay interfaces and tests removed by original /020 and partly restored later. These changes are not advertised as speed optimizations or justified as correctness fixes. The license/lockfile cleanup is separate from hashing.','','The other largest catch-up patches are V2/011 (storage, block transition, candidate selection, Avalanche, pool, Chronik, recovery and development runtime), V2/012 (Chronik wire/database/query/HTTP/runtime), V2/015 (consensus, wallet and functional fixture migration), and V2/024 (fuzzing mixed with production transaction, overlay, validation, state and Avalanche changes). Each is separated below.','','## Complete original-to-new mapping','','Each completed original boundary has the exact original tree. A range denotes sequential parts replacing one original patch. Authorship/date and original rationale are retained in mail metadata; `Original-Commit`, `Original-Patch` and `Split-Concern` trailers identify provenance. The JSON manifest also records every edit span, candidate parent, tree and mailbox filename.','','| Original | New patches | Original subject | Decision |','|---|---|---|']
 for o in m['originals']:
  rs=[bysha[s] for s in o['new_shas']];new=label(rs[0])+('–'+label(rs[-1]) if len(rs)>1 else '')
  lines.append('| '+o['series']+f"/{o['number']:03}"+' | '+new+' | '+o['subject'].replace('|','\\|')+' | '+o['rationale'].replace('|','\\|')+' |')
 lines+=['','## Extracted patch purposes','','| New patch | Purpose | Original |','|---|---|---|']
 for r in m['patches']:
  lines.append('| ['+label(r)+'](../patches/'+r['series']+'/'+r['file']+') | '+r['subject'].replace('|','\\|')+' | '+r['original_patch']+' |')
 lines+=['','## Validation and scope','','`replay-verification.json` checks every exported patch in a temporary Git index, compares every intermediate candidate tree, and compares all 84 completed original boundaries. Both series files are checked against the manifest in order. This proves replay and tree preservation; it does not prove compilation, consensus safety or performance.','','- Original Layer-1 tip: `8ea9ea122a`, tree `'+m['endpoints']['ecash']+'`.','- Original Layer-2 tip: `'+m['original_tip']+'`, tree `'+m['endpoints']['v2']+'`.','- Candidate source tip: `'+m['candidate_tip']+'`.','','No native compile or runtime checks have been run on these newly split boundaries. The active benchmark process owns the machine during timed measurements. Historical build evidence is identified as historical and does not count as a new candidate test.','','The original daemon-only sweep built only baseline, ecash/001–003, and V2/031–032. Forward references exist long before /020, and /020 deletes declarations still used by its own implementation. Reordering or adding explicit prerequisite fixes is a separate review gate. Preserve failure evidence; never infer a pass from clean patch replay.','','## Reproduce','','```sh','python3 daemon/scripts/restructure-optimization-stack.py \\','  --source /path/to/the/original/inner/git/repository \\','  --output-root "$PWD"','python3 daemon/scripts/verify-restructured-stack.py \\','  --source /path/to/the/original/inner/git/repository \\','  --root "$PWD"','python3 daemon/scripts/summarize-restructured-stack.py --root "$PWD"','```','','Run generation only in an isolated candidate outer worktree: it overwrites the generated candidate mailboxes and series. It writes source objects and the candidate source branch in the supplied inner repository but does not check out or reset its active worktree.','','New patch numbers are local to each layer. V2 continues to include `../ecash/series`; no references to old numeric filenames are executable outside the original series on this branch. Historical V1/Doged release manifests and old historical eCash evidence describe different patch sets and remain unchanged.','','Benchmark results keep their original 85-point identities. They must not be relabeled to claim isolated measurements for the newly extracted changes. The manifest is the bridge for a future run.','']
 (audit/'README.md').write_text('\n'.join(lines))
 if a.evidence_root:
  evidence=pathlib.Path(a.evidence_root);rows=[]
  for o in m['originals']:
   path=evidence/'daemon-build-pass'/f"step_{o['step']:03}.json"
   if not path.exists():continue
   d=json.loads(path.read_text());assert d['sha']==o['sha'];errors=[];loghashes=[]
   for cmd in d.get('commands',[]):
    log=evidence/cmd.get('log','')
    if log.is_file():
     content=log.read_bytes();loghashes.append({'path':cmd['log'],'sha256':hashlib.sha256(content).hexdigest()})
     if cmd.get('returncode'):
      errors += [re.sub(r'\x1b\[[0-9;]*m','',l) for l in content.decode(errors='replace').splitlines() if 'error:' in l or 'undefined symbol' in l][:12]
   notes=evidence/'repairs'/f"step_{o['step']:03}_notes.json"
   rows.append({'original_patch':o['series']+f"/{o['number']:03}",'sha':o['sha'],'original_tree':o['tree'],'source_record_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'configure_passed':d.get('configure_passed'),'daemon_build_passed':d.get('daemon_build_passed'),'cache_sha256':d.get('cache_sha256'),'git_metadata_adapter':'Historical sweep applied only its recorded Git worktree metadata compatibility overlay; source compile defects were not repaired.','diagnostics':errors,'log_hashes':loghashes,'benchmark_candidate_repair_notes_not_applied':json.loads(notes.read_text()) if notes.exists() else []})
  (audit/'historical-build-evidence.json').write_text(json.dumps({'schema':1,'scope':'Original unsplit commits only. New split boundaries are not tested by these records. Repairs are evidence only and have not been applied.','records':rows},indent=2)+'\n')
if __name__=='__main__':main()
